llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pirfenidone, a close structural analogue sharing the methyl-phenyl heteroaromatic lactam motif, is rapidly absorbed and displays high oral bioavailability in humans and nonclinical species, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "A DPP-4 inhibitor analogue containing the same pyrazolone-phenyl core as the query has human oral bioavailability of 75–87%, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Structurally related 5-HT3 antagonists are well absorbed orally with reported bioavailability of 50–80%, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Urapidil, a high-transfer analogue, has absolute oral bioavailability of 78% in healthy volunteers, indicating efficient oral absorption and limited first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ondansetron, another high-transfer analogue, has oral bioavailability of about 60% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alogliptin, with a high transfer score, has approximately 100% absolute oral bioavailability, demonstrating that this structural class can achieve essentially complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Duvelisib, despite being a larger and more complex molecule, still has 42% absolute oral bioavailability, supporting that even less favorable analogues exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Ziprasidone, a high-transfer analogue, has approximately 60% absolute oral bioavailability under fed conditions, further supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability well above 20% (42–100%), with the closest structural analogue pirfenidone reported as high; the physicochemical prior is also favorable. Therefore the query molecule is predicted to have absolute oral bioavailability ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "Fasted-state-specific bioavailability data for the query are absent; some analogue data were collected under fed conditions, though they still support high bioavailability.",
    "No explicit first-pass metabolism or transporter data for the query are available, but the consistent high bioavailability across diverse analogues reduces this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

